def policy(obs, P):
    x = obs[0]
    v = obs[1]
    th = obs[2]
    thd = obs[3]
    if x < P['x_thr']:
        return 1
    if th < P['th_thr']:
        return 0
    if thd < P['thd_thr']:
        return 0
    s = P['w_x']*x + P['w_v']*v + P['w_th']*th + P['w_thd']*thd + P['b']
    if s > 0:
        return 1
    else:
        return 0
